// BaseNode.js
// Shared shell for every pipeline node — header, body, and connection handles.
// Pass a config object instead of re-implementing layout in each node type.

import { Handle, Position } from 'reactflow';

/**
 * @typedef {Object} HandleConfig
 * @property {string} id   - Handle suffix (full id becomes `${nodeId}-${id}`)
 * @property {string} [label] - Optional label rendered beside the handle
 * @property {Object} [style] - Optional inline style overrides for positioning
 */

/**
 * @typedef {Object} BaseNodeConfig
 * @property {string} title
 * @property {string} [icon='●']
 * @property {string} [color='#6366f1'] - Accent color for header, handles, and focus ring
 * @property {HandleConfig[]} [inputs=[]]
 * @property {HandleConfig[]} [outputs=[]]
 * @property {number} [width=220]
 * @property {number} [minHeight=90]
 * @property {number} [height] - Fixed height when auto-sizing nodes need explicit bounds
 * @property {string} [className] - Extra classes on the root card
 */

/**
 * Computes vertical position for evenly spaced handles along a node edge.
 */
const handleTop = (index, total) =>
  total === 1 ? '50%' : `${((index + 1) / (total + 1)) * 100}%`;

/**
 * BaseNode — reusable pipeline node card.
 *
 * @param {Object} props
 * @param {string} props.id - React Flow node id
 * @param {BaseNodeConfig} props.config
 * @param {React.ReactNode} [props.children] - Custom content rendered in the body
 */
export const BaseNode = ({ id, config, children }) => {
  const {
    title,
    icon = '●',
    color = '#6366f1',
    inputs = [],
    outputs = [],
    width = 220,
    minHeight = 90,
    height,
    className = '',
  } = config;

  const rootStyle = {
    width,
    minHeight,
    ...(height ? { height } : {}),
    '--node-accent': color,
  };

  return (
    <div className={`base-node ${className}`.trim()} style={rootStyle}>
      {inputs.map((handle, i) => (
        <Handle
          key={handle.id}
          type="target"
          position={Position.Left}
          id={`${id}-${handle.id}`}
          style={{ top: handleTop(i, inputs.length), ...handle.style }}
          className="node-handle node-handle--input"
        >
          {handle.label && (
            <span className="handle-label handle-label--left">{handle.label}</span>
          )}
        </Handle>
      ))}

      <div className="node-header" style={{ background: color }}>
        <span className="node-icon">{icon}</span>
        <span className="node-title">{title}</span>
      </div>

      <div className="node-body">{children}</div>

      {outputs.map((handle, i) => (
        <Handle
          key={handle.id}
          type="source"
          position={Position.Right}
          id={`${id}-${handle.id}`}
          style={{ top: handleTop(i, outputs.length), ...handle.style }}
          className="node-handle node-handle--output"
        >
          {handle.label && (
            <span className="handle-label handle-label--right">{handle.label}</span>
          )}
        </Handle>
      ))}
    </div>
  );
};
